mapper.insert:
insert into ai_chat_session (
    student_id, student_code, title, status, message_count, last_message_at,
    summary, summary_token_count, compressed_until_message_id, archive_status,
    archive_id, expire_at, created_at, updated_at
) values (
    #{studentId}, #{studentCode}, #{title}, #{status}, #{messageCount}, #{lastMessageAt},
    #{summary}, #{summaryTokenCount}, #{compressedUntilMessageId}, #{archiveStatus},
    #{archiveId}, #{expireAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
select *
from ai_chat_session
where id = #{id}
  and student_id = #{studentId}
  and status = 'ACTIVE'

mapper.update:
update ai_chat_session
set title = #{title}, updated_at = now()
where id = #{id}
  and student_id = #{studentId}
  and status = 'ACTIVE'

update ai_chat_session
set status = #{status}, updated_at = now()
where id = #{id}
  and student_id = #{studentId}

update ai_chat_session
set message_count = (
        select count(*)
        from ai_chat_message
        where session_id = #{id}
    ),
    last_message_at = coalesce((
        select max(created_at)
        from ai_chat_message
        where session_id = #{id}
    ), last_message_at),
    updated_at = now()
where id = #{id}
